namespace Ordering;

/// <summary>Applies tier, override and channel adjustments to an order subtotal.</summary>
public sealed class PricingRules
{
    public decimal ApplyAdjustments(Order order, CustomerTier tier)
    {
        var subtotal = CalculateSubtotal(order);

        if (tier == CustomerTier.Blocked)
            return 0m;

        var adjusted = ApplyTierAdjustment(subtotal, tier);
        adjusted = ApplyDiscountOverride(adjusted, order.DiscountOverride.GetValueOrDefault());
        adjusted = ApplyVolumeDiscount(adjusted, subtotal);
        adjusted = ApplyChannelAdjustment(adjusted, order.Channel);

        return adjusted < 0m ? 0m : adjusted;
    }

    private static decimal CalculateSubtotal(Order order)
    {
        decimal subtotal = 0m;
        foreach (var line in order.Lines)
            subtotal += line.UnitPrice * line.Quantity;

        return subtotal;
    }

    private static decimal ApplyTierAdjustment(decimal amount, CustomerTier tier)
    {
        return tier == CustomerTier.Wholesale ? amount * 0.95m : amount;
    }

    private static decimal ApplyDiscountOverride(decimal amount, decimal discount)
    {
        return discount > 0m ? amount - discount : amount;
    }

    private static decimal ApplyVolumeDiscount(decimal amount, decimal subtotal)
    {
        return subtotal > 500m ? amount - 10m : amount;
    }

    private static decimal ApplyChannelAdjustment(decimal amount, OrderChannel channel)
    {
        return channel switch
        {
            OrderChannel.Web => amount,
            OrderChannel.Phone => amount + 2m,
            OrderChannel.Marketplace => amount * 1.02m,
            _ => amount,
        };
    }
}
